data.cypher_query:
OPTIONAL MATCH (c:Customer)-[:PLACED]->(o:Order)
RETURN c.Customer_Name AS Customer, COUNT(o) AS Total_Orders
ORDER BY Total_Orders DESC;

OPTIONAL MATCH (s:Sales)-[:PROCESSED]->(o:Order)
RETURN s.Name AS Sales_Consultant, SUM(o.Total_Cost) AS Total_Revenue
ORDER BY Total_Revenue DESC;

OPTIONAL MATCH (c:Customer)
RETURN c.Region AS Region, COUNT(c) AS Total_Customers
ORDER BY Total_Customers DESC;

OPTIONAL MATCH (o:Order)-[:CONTAINS]->(p:Product)
RETURN p.Product_Name AS Product, AVG(o.Total_Cost) AS Average_Order_Value
ORDER BY Average_Order_Value DESC;

OPTIONAL MATCH (s:Sales)-[:CONDUCTED]->(m:Meeting)
RETURN s.Name AS Sales_Consultant, COUNT(m) AS Meetings_Conducted
ORDER BY Meetings_Conducted DESC;

OPTIONAL MATCH (c:Customer)-[:PLACED]->(o:Order)-[:CONTAINS]->(p:Product)
RETURN c.Customer_Name AS Customer, COUNT(DISTINCT p.Product_Name) AS Product_Variety
ORDER BY Product_Variety DESC;

OPTIONAL MATCH (c:Customer)-[:PLACED]->(o:Order)-[:CONTAINS]->(p:Product {Category: 'Dairy and Eggs'})
RETURN c.Region AS Region, SUM(o.Total_Cost) AS Total_Revenue
ORDER BY Total_Revenue DESC;

OPTIONAL MATCH (s:Sales)-[:ATTENDED]->(p:ProfessionalDevelopment)
RETURN p.Event_Date AS EventDate, COUNT(s) AS Attendance_Count
ORDER BY EventDate;

OPTIONAL MATCH (o:Order)-[:CONTAINS]->(p:Product)
RETURN p.Category AS Category, AVG(o.Cost_Per_Unit) AS AvgCostPerUnit
ORDER BY AvgCostPerUnit DESC;

OPTIONAL MATCH (s:Sales)-[:CONDUCTED]->(m:Meeting)<-[:PARTICIPATED_IN]-(c:Customer)
RETURN s.Name AS Sales_Consultant, COUNT(DISTINCT c.Customer_ID) AS UniqueCustomers
ORDER BY UniqueCustomers ASC LIMIT 5;

OPTIONAL MATCH (p:Product)
WHERE p.Category = 'Produce'
RETURN p.Product_ID, p.Product_Name;

OPTIONAL MATCH (p:Product)
WHERE p.Product_Name = 'Fresh Apples'
RETURN p.Product_ID, p.Product_Name, p.Category;

OPTIONAL MATCH (p:Product)
WHERE p.Product_ID >= 'FD0001' AND p.Product_ID <= 'FD0030'
RETURN p.Product_ID, p.Product_Name;

OPTIONAL MATCH (p:Product)
WHERE p.Product_ID IN ['FD0001', 'FD0012', 'FD0035']
RETURN p.Product_ID, p.Product_Name;

OPTIONAL MATCH (s:Sales)-[:CONDUCTED]->(m:Meeting)
OPTIONAL MATCH (m)<-[:PARTICIPATED_IN]-(c:Customer {Region: "Africa"})
RETURN s.Name AS SalesConsultantName, COUNT(m) AS MeetingsCount;

OPTIONAL MATCH (c:Customer {Customer_Name: 'James Black'})-[:PLACED]->(o:Order)
OPTIONAL MATCH (o)-[:CONTAINS]->(p:Product)
RETURN p.Product_Name, p.Category, p.Product_ID;

OPTIONAL MATCH (m:Meeting)<-[:PARTICIPATED_IN]-(c:Customer)
WHERE m.Meeting_Details = "Product Demonstration" AND m.Delivery_Type = "Hybrid"
RETURN m.Meeting_ID, c.Customer_ID, m.Meeting_Date, m.Meeting_Time;

OPTIONAL MATCH (m:Meeting)<-[:PARTICIPATED_IN]-(c:Customer)
WHERE m.Meeting_Details = "Contract Negotiation" AND m.Delivery_Type = "In-person"
RETURN m.Meeting_ID, c.Customer_ID, m.Meeting_Date, m.Meeting_Time;

OPTIONAL MATCH (s:Sales)
RETURN s.Sysco_Lab_Branch, COUNT(s) AS NumberOfSalesConsultants
ORDER BY NumberOfSalesConsultants DESC;
